package com.example.solarfarm.domain;

import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="predictions") public class Prediction {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="panel_id") private Panel panel; @Column(nullable=false) private Instant timestamp;
 @Column(name="actual_power_w",nullable=false) private double actualPowerW; @Column(name="expected_power_w",nullable=false) private double expectedPowerW; @Column(name="deviation_w",nullable=false) private double deviationW; @Column(name="deviation_percent",nullable=false) private double deviationPercent; @Column(nullable=false) private boolean anomaly; @Column(name="anomaly_score",nullable=false) private double anomalyScore; @Column(name="fault_type",nullable=false) private String faultType; @Column(nullable=false) private double confidence; @Column(nullable=false) private String severity; @Column(name="model_version",nullable=false) private String modelVersion; @Column(name="created_at",nullable=false) private Instant createdAt=Instant.now();
 protected Prediction(){} public Prediction(Panel p,Instant t,double actual,double expected,double deviation,double percent,boolean a,double score,String fault,double conf,String sev,String version){panel=p;timestamp=t;actualPowerW=actual;expectedPowerW=expected;deviationW=deviation;deviationPercent=percent;anomaly=a;anomalyScore=score;faultType=fault;confidence=conf;severity=sev;modelVersion=version;}
 public Long getId(){return id;} public Panel getPanel(){return panel;} public Instant getTimestamp(){return timestamp;} public double getActualPowerW(){return actualPowerW;} public double getExpectedPowerW(){return expectedPowerW;} public double getDeviationW(){return deviationW;} public double getDeviationPercent(){return deviationPercent;} public boolean isAnomaly(){return anomaly;} public double getAnomalyScore(){return anomalyScore;} public String getFaultType(){return faultType;} public double getConfidence(){return confidence;} public String getSeverity(){return severity;} public String getModelVersion(){return modelVersion;}
}
